-- ds_tolerance — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_tolerance.
-- The latest tolerance advice per key attribute and where it has got to. Pipeline: Tolerance advice.

SELECT p.cde_id, p.cde_name, p.criticality, e.business_domain, p.proposed_ts,
       p.register_tolerance_pct AS tolerance_pct, p.advice, p.proposed_tolerance_pct,
       p.runs_observed, p.runs_outside, p.latest_fail_pct, p.rationale, p.review_state,
       p.latest_reviewer, p.latest_reason
FROM   sdpt_data_trnf.udp_brnz.dq_results_v_tolerance_proposal_current p
LEFT JOIN sdpt_data_trnf.udp_brnz.dq_config_v_cde_registry_current e ON e.cde_id = p.cde_id
